history-copy.cpp.content:
float history[256]; std::atomic<unsigned> cursor;
void process() { history[cursor++ % 256] = sample(); }
void draw() { auto before = cursor.load(); float frame[256]; std::copy(history, history + 256, frame); if (before != cursor.load()) return; draw(frame); }

