static PEAK: AtomicU32 = AtomicU32::new(0);
fn process(peak: f32) { PEAK.store(peak.to_bits(), Ordering::Relaxed); }
fn draw() -> f32 { f32::from_bits(PEAK.load(Ordering::Relaxed)) }

